import{_ as r,a as t,c as s,ac as a}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"网络：能 ping 但业务连接失败的复盘","description":"目标主机可以 ping 通，业务端口却连接超时。按证据定位原因，说明恢复步骤与验收条件。","frontmatter":{"title":"网络：能 ping 但业务连接失败的复盘","description":"目标主机可以 ping 通，业务端口却连接超时。按证据定位原因，说明恢复步骤与验收条件。","showdocs":{"topics":[{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"网络：分层、寻址与证据","summary":"目标主机可以 ping 通，业务端口却连接超时。按证据定位原因，说明恢复步骤与验收条件。","status":"active","related":[{"title":"网络：离线推演 DNS 与双向路径证据","link":"/systems/network-remote/network/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"网络配置与诊断 操作与命令","link":"/systems/network-remote/network/plus/ecosystem/network-general-general","kind":"命令与对象入口","scope":"general","audience":"general"},{"title":"OSI 与 TCP/IP 分层笔记","link":"/systems/network-remote/network/plus/subjects/networkengineerbase","kind":"知识专题","scope":"general","audience":"general"},{"title":"TCP/IP","link":"/systems/network-remote/network/plus/subjects/tcpip","kind":"知识专题","scope":"general","audience":"general"},{"title":"网络：地址、端口、DNS 与基本观察","link":"/systems/network-remote/network/base/basic/start","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"网络排障：变更窗口、路径证据与 TLS","link":"/systems/network-remote/network/troubleshooting"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"网络排障：变更窗口、路径证据与 TLS","link":"/systems/network-remote/network/troubleshooting"},"next":false},"headers":[],"relativePath":"systems/network-remote/network/pro/review/review.md","filePath":"systems/network-remote/network/pro/review/review.md"}'),i={name:"systems/network-remote/network/pro/review/review.md"};function o(n,e,l,c,p,h){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="网络-能-ping-但业务连接失败的复盘" tabindex="-1">网络：能 ping 但业务连接失败的复盘 <a class="header-anchor" href="#网络-能-ping-但业务连接失败的复盘" aria-label="Permalink to &quot;网络：能 ping 但业务连接失败的复盘&quot;">​</a></h1><p>本篇从具体故障组织排查、恢复与验收，再用后面的场景题检查机制理解。复盘应说明哪些证据支持原因，以及什么检查能够防止再次发生。</p><h2 id="incident-scenario" tabindex="-1">故障场景与影响 <a class="header-anchor" href="#incident-scenario" aria-label="Permalink to &quot;故障场景与影响 {#incident-scenario}&quot;">​</a></h2><p>目标主机可以 ping 通，业务端口却连接超时。</p><p>先记录首次异常时间、受影响对象和最近变更，区分个别对象失败与整条管理链路异常。以下是排查演练，不是已发生事故的实测记录。</p><h2 id="incident-evidence" tabindex="-1">按证据定位原因 <a class="header-anchor" href="#incident-evidence" aria-label="Permalink to &quot;按证据定位原因 {#incident-evidence}&quot;">​</a></h2><ol><li>记录客户端实际解析结果、IPv4/IPv6 选择、源地址与目标端口，确认请求没有进入错误代理。</li><li>在目标核对监听地址和服务状态，将连接拒绝与持续无响应分开记录。</li><li>检查正向与回程路由、两侧访问控制；必要时用时间匹配的两端抓包判断请求和响应停在哪里。</li></ol><h2 id="incident-recovery" tabindex="-1">恢复步骤与验收 <a class="header-anchor" href="#incident-recovery" aria-label="Permalink to &quot;恢复步骤与验收 {#incident-recovery}&quot;">​</a></h2><p>依据失败层修复具体监听、解析、路由或规则；网络变更先保留管理路径与旧配置，一次改变一个可验证条件。</p><p>验收：从原客户端发起实际协议请求并核对目标响应，兼顾回程和原应拒绝的访问。只恢复 ICMP 或只在服务器本地测试不算业务恢复。</p><p>将触发条件、直接原因、修复动作、恢复证据和后续检查写入同一份复盘，明确每项后续工作的负责人。机制参考：<a href="https://docs.aws.amazon.com/vpc/latest/userguide/vpc-network-acls.html" target="_blank" rel="noopener noreferrer">官方说明</a>。</p><h2 id="check" tabindex="-1">机制自检 <a class="header-anchor" href="#check" aria-label="Permalink to &quot;机制自检 {#check}&quot;">​</a></h2><p>自检：根据上面的场景画出故障链，标出每一项证据来自哪个对象、发生在哪个时间。说明恢复动作改变了什么，以及为什么其他原本允许或拒绝的操作仍符合预期。</p><h2 id="answers" tabindex="-1">参考解答与误区 <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;参考解答与误区 {#answers}&quot;">​</a></h2><p>问题一：同一名字NXDOMAIN与SERVFAIL分别说明什么？</p><p>答案：NXDOMAIN是该查询名字不存在，SERVFAIL表示服务器无法完成解析。先记录解析器、查询类型和时间；刷新本机缓存不能修复权威错误。</p><p>问题二：SYN在服务端可见，客户端一直超时，能否断言目标应用故障？</p><p>答案：不能。仍需检查服务端是否响应、响应走哪个返回路径、是否被过滤，以及当前抓包点是否正确。应用日志与路由证据应对齐时钟。</p><p>问题三：显示过滤只留下DNS包，原始抓包是否已经脱敏？</p><p>答案：没有。显示过滤只隐藏其他包，原文件仍含全部捕获内容。分享前应按授权另行最小化材料并限制保留期。</p><h2 id="acceptance" tabindex="-1">验收与未验证项 <a class="header-anchor" href="#acceptance" aria-label="Permalink to &quot;验收与未验证项 {#acceptance}&quot;">​</a></h2><p>验收应覆盖正常操作、预期拒绝和恢复后的再次操作，并记录实际版本、身份、配置及结果。本文示例未执行；配置审阅与离线推演不能替代真实环境的连通、权限和恢复验证。</p><h2 id="sources" tabindex="-1">版本、来源与进一步阅读 <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;版本、来源与进一步阅读 {#sources}&quot;">​</a></h2><p>核对日期：2026-10-17。教学版本族：RFC1034/1035、TCP/IP基础、Wireshark4.x与W3C WebRTC规范。固定源码用于重现字段，动态官方网页用于补充说明，不称为2026最新版本。中文检索参考微软中文访问控制与FRP中文文档，英文检索核对协议、手册与固定标签；结论按本课范围独立组织。</p><ul><li><a href="https://www.rfc-editor.org/info/rfc1034/" target="_blank" rel="noopener noreferrer">RFC1034 DNS基础</a></li><li><a href="https://www.wireshark.org/docs/wsug_html_chunked/ChWorkDisplayFilterSection.html" target="_blank" rel="noopener noreferrer">Wireshark显示过滤</a></li><li><a href="https://www.w3.org/TR/webrtc/" target="_blank" rel="noopener noreferrer">W3C WebRTC</a></li></ul><h2 id="historical" tabindex="-1">历史资料与取舍 <a class="header-anchor" href="#historical" aria-label="Permalink to &quot;历史资料与取舍 {#historical}&quot;">​</a></h2><p>旧HTTP、CDN、代理与音视频材料在这里保持可达。CDN并不总选择地理最近节点；缓存行为还受配置与请求约束影响。HTTP的no-cache允许存储，但复用前需要验证，不能理解成一律不缓存。旧TCP握手图最后一步写成SYN的笔误不沿用。下列旧正文是历史参考，兼容锚点、主题与URL均保留；本课不把参考目录包装成已经重新实现的WebRTC或HTTP课程。</p><ul><li><a href="/systems/network-remote/network/plus/troubleshooting/http-tls-error">HTTPS 证书校验失败</a>: 保留HTTP客户端校验失败这一主场景；域名、期限、链与时间经验吸收入证书管理，但不改变旧primary主题或URL。</li><li><a href="/systems/network-remote/network/plus/ecosystem/cmd-curl">curl</a>: 全文核对请求、下载、代理、Cookie与表单示例；保留工具场景，网络新课只吸收按解析与连接分层取证，不扩写HTTP客户端教程。</li><li><a href="/systems/network-remote/network/plus/practice/frp">FRP 客户端与服务端 INI 配置</a>: 全文核对两组INI及客户端/服务端角色；弱令牌、Dashboard明文与公网通配监听为历史配置，不继承到新实践。</li><li><a href="/systems/network-remote/network/plus/practice/linux-vpn-clash">clash</a>: 全文核对Compose、DNS、控制端口和规则；MATCH在私网直连规则之前会遮蔽后续规则，172.12/172.13并非RFC1918私网。保留原记录，新课讲代理与路由边界，不推荐照抄暴露监听。</li><li><a href="/systems/network-remote/network/plus/practice/linux-vpn-v2fly-core">v2fly-core</a>: 全文核对Compose、挂载和截图依赖；缺完整导出配置，不冒称完整VPN工程，新课以离线边界推演补足概念。</li><li><a href="/systems/network-remote/network/plus/subjects/ssh-工具">ssh 工具</a>: 全文仅MobaXterm/Xshell名称，保留工具选型参考；新课补客户端格式、主机信任及用户授权，不伪称旧页已有教程。</li><li><a href="/systems/operating-systems/macos/plus/subjects/mac-mini">Mac mini 开发环境配置记录</a>: 全文读取环境变量和网络设置；保留Java14/Go1.14等历史公司环境，网络吸收代理/解析观察点，明确172.12/172.13地址不能视为私网。</li><li><a href="/systems/operating-systems/windows/plus/troubleshooting/error">翻译工具干扰 SSH Ctrl+C 的记录</a>: 全文读取词霸秒译触发Ctrl+C记录；吸收本地输入工具干扰会话的排错维度，不据此修改认证或网络。</li><li><a href="/systems/operating-systems/windows/plus/ecosystem/开发笔记">Windows 端口、服务与 DNS 操作</a>: 全文读取端口进程、服务、hosts和DNS刷新；保留Windows命令入口，新课明确刷新本机缓存不能修复权威记录。</li><li><a href="/systems/network-remote/network/plus/subjects/networkengineerbase">OSI 与 TCP/IP 分层笔记</a>: 全文读取四层表与兼容锚点；吸收按层职责定位，不把OSI七层与TCP/IP四层数目混用。</li><li><a href="/systems/network-remote/network/plus/ecosystem/http">HTTP协议</a>: 分三段读取1–50、51–95、96–140全部140行，包括长响应头表；保留HTTP方法/状态/媒体类型参考。旧Servlet/Netscape解释和按版本新增方法的简化陈述不当作现行规范，本课不接管HTTP主专题。</li><li><a href="/systems/network-remote/network/plus/subjects/tcpip">TCP/IP</a>: 全文读取TCP字段、握手/挥手图和UDP空节；吸收序号、ACK与字节流，修正第三次握手通常ACK而不是再次SYN；不承诺TCP可靠性等于业务成功。</li><li><a href="/systems/network-remote/network/plus/subjects/cdn">CDN</a>: 全文读取CDN原理、更新与取舍；吸收边缘/源站分离，明确地理最近不是必然，no-cache允许存储但要求复用前验证，不继承不缓存的简化结论。</li><li><a href="/systems/network-remote/network/plus/subjects/http">HTTP 版本与状态码入门草稿</a>: 全文读取HTTP版本、TCP/UDP表、状态码与HTTPS/攻击占位；保留入门草稿，未填充段不冒称完整安全课程；新网络课不扩张Web协议范围。</li><li><a href="/systems/security-access/security/plus/ecosystem/casbin-model">Casbin Model 请求、策略与角色定义</a>: 全文读取r/p/g、allow效应与matcher；吸收主体资源动作和RBAC模型，明确旧allow模型并非天然拒绝优先，新课独立教学决策器给出冲突反例。</li><li><a href="/systems/security-access/security/plus/subjects/casbin-base">Casbin base</a>: 全文读取功能与不能完成的认证/用户管理；吸收认证授权分工，超级用户为显式模型设计而非所有系统默认旁路。</li><li><a href="/systems/network-remote/network/wireshark(介绍)">Wireshark 资料入口</a>: 全文读取官网与过滤入口；保留下载参考，不将工具下载链接当完整抓包教程。</li><li><a href="/systems/network-remote/network/plus/ecosystem/wireshark(过滤表达式)">Wireshark(过滤表达式)</a>: 全文读取ip.src/ip.dst与ip.addr等价显示过滤写法；吸收端点选择，补捕获过滤与显示过滤不可互换及原文件隐私边界。</li><li><a href="/systems/network-remote/network/plus/practice/utils-frp">frp 0.29.1 内网穿透记录</a>: 全文读取0.29.1目录、两端INI、启动及Nginx段；保留历史版本URL，不继承弱口令和0.0.0.0代理目标；新课以0.61.1固定字段说明时代差异。</li><li><a href="/systems/operating-systems/windows/plus/practice/hyper-v">Hyper-V 安装 CentOS 7 记录</a>: 全文读取图片引用、ifcfg与工具清单；保留CentOS7历史。192.0.2.10在所示/24网段是广播地址，ONBOOT=no也不代表自动启用；新课明确网关与前缀关系。图片未做视觉复核，不声称图内步骤已验。</li><li><a href="/principles/protocols/webrtc/webrtc">WebRTC</a>: 全文104行读取目标、信令、NAT类型、STUN/TURN/ICE与补充实践；保留webrtc原ID及主题。吸收信令与媒体路径分离，不将旧NAT四分类当打洞保证。</li><li><a href="/principles/protocols/webrtc/coturn-搭建">Coturn 搭建</a>: 全文147行读取依赖、证书、TURN配置、4.5.1.3/OpenSSL1.0.2历史日志和候选结果；保留旧ID/URL，不继承99999天证书、静态弱口令或默认开放中继。</li></ul>',28)])])}const w=r(i,[["render",o]]);export{k as __pageData,w as default};
